change('src/metal/MetalWorld.mm', '                qualityNv <=\n                    layout.qualityDispatch\n                        .directMaximumGeneralizedVelocities &&\n                qualityRows <=\n                    layout.qualityDispatch.directMaximumRows', '                (qualityNv <= MR_UNIFIED_QUALITY_MAX_ADJACENT_VELOCITIES ||\n                 (qualityNv <=\n                    layout.qualityDispatch\n                        .directMaximumGeneralizedVelocities &&\n                  qualityRows <=\n                    layout.qualityDispatch.directMaximumRows))')
change('src/metal/MetalWorld.mm', '            generalizedVelocityCount <=\n                    config.quality\n                        .directMaximumGeneralizedVelocities &&\n                qualityRowCount <=\n                    config.quality.directMaximumRows', '            (generalizedVelocityCount <= MR_UNIFIED_QUALITY_MAX_ADJACENT_VELOCITIES ||\n             (generalizedVelocityCount <=\n                    config.quality\n                        .directMaximumGeneralizedVelocities &&\n              qualityRowCount <=\n                    config.quality.directMaximumRows))')
